// State name normalizer for robust matching
export function normalizeStateName(str) {
  if (!str) return '';
  let norm = str
    .toLowerCase()
    .replace(/[āáàâä]/g, 'a')
    .replace(/[ēéèêë]/g, 'e')
    .replace(/[īíìîï]/g, 'i')
    .replace(/[ōóòôö]/g, 'o')
    .replace(/[ūúùûü]/g, 'u')
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]/g, '');
  if (norm === 'orissa') return 'odisha';
  if (norm === 'uttaranchal') return 'uttarakhand';
  if (norm === 'pondicherry') return 'puducherry';
  return norm;
}

export const IndiaStateBorders = memo(function IndiaStateBorders({
  selectedState,
  hoveredState,
  onSelectState,
  onHoverState,
  stationCounts = {},
  zoom = 1,
}) {
  const normSelected = normalizeStateName(selectedState);
  const normHovered = normalizeStateName(hoveredState);

  return (
    <g id="state-features" className="state-boundaries-layer">
      {INDIA_STATES.map((state) => {
        const normName = normalizeStateName(state.name);
        const isSelected = normSelected && normSelected !== 'all' && normSelected === normName;
        const isHovered = normHovered && normHovered === normName;

        // Count stations for this state
        const count = stationCounts[state.name] || 0;

        let fill = '#0A0A0A';
        let stroke = '#374151';
        let strokeWidth = '0.8';
        let opacity = 1;

        if (isSelected) {
          fill = '#1c1c1c';
          stroke = '#EAEAEB';
          strokeWidth = '1.6';
          opacity = 1;
        } else if (isHovered) {
          fill = '#141414';
          stroke = '#6b7280';
          strokeWidth = '1.2';
          opacity = 1;
        } else if (count > 0) {
          fill = '#0d0d0d';
          stroke = '#374151';
        }

        return (
          <path
            key={state.id}
            id={state.id}
            className={`state-path ${isSelected ? 'selected' : ''} ${isHovered ? 'hovered' : ''}`}
            d={state.d}
            fill={fill}
            stroke={stroke}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            opacity={opacity}
            style={{
              cursor: 'pointer',
              transition: 'fill 0.15s ease, stroke 0.15s ease, stroke-width 0.15s ease',
            }}
            onClick={(e) => {
              e.stopPropagation();
              if (onSelectState) {
                onSelectState(isSelected ? 'all' : state.name);
              }
            }}
            onMouseEnter={() => onHoverState && onHoverState(state.name)}
            onMouseLeave={() => onHoverState && onHoverState(null)}
          >
            <title>{`${state.name}${count ? ` (${count} DWLR stations)` : ''}`}</title>
          </path>
        );
      })}

      {/* State Labels when hovered, selected, or at high zoom with stations */}
      {INDIA_STATES.map((state) => {
        const normName = normalizeStateName(state.name);
        const isSelected = normSelected && normSelected !== 'all' && normSelected === normName;
        const isHovered = normHovered && normHovered === normName;
        const count = stationCounts[state.name] || 0;

        // Show labels for selected/hovered state, or at zoom >= 2.0 for states with stations
        const shouldShowLabel = isSelected || isHovered || (zoom >= 2.0 && count > 0);
        if (!shouldShowLabel) return null;

        return (
          <g
            key={`lbl-${state.id}`}
            pointerEvents="none"
            transform={`translate(${state.cx}, ${state.cy})`}
          >
            <rect
              x="-45"
              y="-12"
              width="90"
              height="20"
              rx="4"
              fill="#000000"
              stroke="#374151"
              strokeWidth="1"
            />
            <text
              x="0"
              y="2"
              textAnchor="middle"
              fill="#EAEAEB"
              fontSize="9"
              fontWeight="600"
              letterSpacing="0.2px"
            >
              {state.name}
            </text>
          </g>
        );
      })}
    </g>
  );
});

export default IndiaStateBorders;
